import { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

interface OutlineFillTrackTextProps {
  leadText?: string;
  valueText?: string;
  fontSize?: number;
  fontWeight?: number;
  color?: string;
  outlineColor?: string;
  outlineWidth?: number;
  backgroundColor?: string;
  glowColor?: string;
  enterOffset?: number;
  anchorOffsetX?: number;
  trackDistance?: number;
  wordGap?: number;
  endPadding?: number;
  fillDuration?: number;
  speed?: number;
  className?: string;
}

const outlineFillTrackTextLength = 80;

const ENTER_END = 16;
const TRACK_START = 16;
const TRACK_END = 72;
const FILL_START = 34;
const FILL_PREFILL = 10;
const FONT_FAMILY = "Arial, Helvetica, sans-serif";
const clamp = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

function estimateTextWidth(
  text: string,
  fontSize: number,
  fontWeight: number,
): number {
  if (typeof document === "undefined") {
    return text.length * fontSize * 0.56;
  }

  const context = document.createElement("canvas").getContext("2d");
  if (!context) return text.length * fontSize * 0.56;
  context.font = `${fontWeight} ${fontSize}px Arial`;
  return context.measureText(text).width;
}

function OutlineFillTrackTextBase({
  leadText = "Keep",
  valueText = "100%",
  fontSize = 368,
  fontWeight = 700,
  color = "#f4f3f6",
  outlineColor = "#e6e2ed",
  outlineWidth = 3,
  backgroundColor = "#030012",
  glowColor = "#64109a",
  enterOffset = 240,
  anchorOffsetX = -84,
  trackDistance = 0,
  wordGap = 220,
  endPadding = 96,
  fillDuration = 38,
  speed = 1,
  className,
}: OutlineFillTrackTextProps) {
  const frame = useCurrentFrame() * Math.max(speed, 0);
  const { width: compositionWidth } = useVideoConfig();
  const safeFontSize = Math.max(fontSize, 1);
  const safeFontWeight = Math.max(fontWeight, 1);
  const safeOutlineWidth = Math.max(outlineWidth, 0);
  const safeGap = Math.max(wordGap, 0);
  const safeEndPadding = Math.max(endPadding, 0);
  const safeFillDuration = Math.max(fillDuration, 1);

  const measurements = useMemo(() => {
    const leadWidth = estimateTextWidth(leadText, safeFontSize, safeFontWeight);
    const valueWidth = estimateTextWidth(
      valueText,
      safeFontSize,
      safeFontWeight,
    );
    return {
      valueWidth,
      distance: leadWidth / 2 + safeGap + valueWidth / 2,
    };
  }, [leadText, safeFontSize, safeFontWeight, safeGap, valueText]);

  const valueOffset = trackDistance > 0 ? trackDistance : measurements.distance;
  const anchorX = compositionWidth / 2 + anchorOffsetX;
  const trailingOverflow = Math.max(
    0,
    anchorX + measurements.valueWidth / 2 - (compositionWidth - safeEndPadding),
  );
  const travelDistance = valueOffset + trailingOverflow;
  const enterProgress = interpolate(frame, [0, ENTER_END], [0, 1], {
    ...clamp,
    easing: Easing.bezier(0.16, 0.84, 0.24, 1),
  });
  const trackProgress = interpolate(frame, [TRACK_START, TRACK_END], [0, 1], {
    ...clamp,
    easing: Easing.bezier(0.42, 0, 0.58, 1),
  });
  const fillProgress = interpolate(
    frame,
    [FILL_START - FILL_PREFILL, FILL_START + safeFillDuration],
    [0, 1],
    clamp,
  );
  const leadY = enterOffset * (1 - enterProgress);
  const revealEdge = enterProgress * 112 - 8;
  const revealSolid = Math.max(0, Math.min(100, revealEdge - 10));
  const revealFade = Math.max(0, Math.min(100, revealEdge + 10));
  const leadMask = `linear-gradient(180deg, #000 0%, #000 ${revealSolid}%, transparent ${revealFade}%, transparent 100%)`;
  const glowOpacity = interpolate(
    enterProgress,
    [0, 0.18, 0.72, 1],
    [0.92, 1, 0.52, 0],
    clamp,
  );
  const fieldY = interpolate(enterProgress, [0, 1], [-42, -210], clamp);
  const textStyle = {
    display: "block",
    fontFamily: FONT_FAMILY,
    fontSize: safeFontSize,
    fontWeight: safeFontWeight,
    letterSpacing: 0,
    lineHeight: 0.86,
    whiteSpace: "nowrap" as const,
  };

  return (
    <div
      className={className}
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        backgroundColor,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `radial-gradient(ellipse 118% 66% at 50% -12%, ${glowColor} 0%, ${glowColor} 14%, transparent 76%)`,
          filter: `blur(${safeFontSize * 0.15}px)`,
          opacity: glowOpacity,
          pointerEvents: "none",
          transform: "translateZ(0)",
        }}
      />

      <div
        style={{
          position: "absolute",
          top: "50%",
          left: `calc(50% + ${anchorOffsetX}px)`,
          transform: `translate3d(${-travelDistance * trackProgress}px, -50%, 0)`,
        }}
      >
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            color,
            maskImage: leadMask,
            maskRepeat: "no-repeat",
            opacity: 1,
            transform: `translate3d(-50%, calc(-50% + ${leadY}px), 0)`,
            WebkitMaskImage: leadMask,
            WebkitMaskRepeat: "no-repeat",
            ...textStyle,
          }}
        >
          {leadText}
        </div>

        <div
          style={{
            position: "absolute",
            top: 0,
            left: valueOffset,
            transform: "translate3d(-50%, -50%, 0)",
            visibility: frame < FILL_START ? "hidden" : "visible",
          }}
        >
          <span
            style={{
              ...textStyle,
              color: "transparent",
              paintOrder: "stroke fill",
              WebkitTextStroke: `${safeOutlineWidth}px ${outlineColor}`,
            }}
          >
            {valueText}
          </span>
          <span
            style={{
              ...textStyle,
              position: "absolute",
              inset: 0,
              clipPath: `inset(0 ${100 - fillProgress * 100}% 0 0)`,
              color,
              opacity: 1,
            }}
          >
            {valueText}
          </span>
        </div>

        <div
          style={{
            position: "absolute",
            top: fieldY,
            left: 0,
            width: safeFontSize * 2.8,
            height: safeFontSize * 0.72,
            background: `radial-gradient(ellipse at center, ${backgroundColor} 0%, ${backgroundColor} 18%, transparent 74%)`,
            filter: `blur(${safeFontSize * 0.07}px)`,
            opacity: glowOpacity,
            pointerEvents: "none",
            transform: "translate3d(-50%, -50%, 0)",
          }}
        />
      </div>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  leadText: {
    type: "text-content",
    default: "Keep",
    description: "Lead text",
  },
  valueText: {
    type: "text-content",
    default: "100%",
    description: "Outlined value",
  },
  fontSize: {
    type: "number",
    min: 120,
    max: 520,
    step: 4,
    default: 368,
    description: "Font size",
    hiddenFromList: false,
  },
  enterOffset: {
    type: "number",
    min: 0,
    max: 420,
    step: 4,
    default: 240,
    description: "Vertical entrance offset",
    hiddenFromList: false,
  },
  anchorOffsetX: {
    type: "number",
    min: -400,
    max: 400,
    step: 4,
    default: -84,
    description: "Shared horizontal anchor offset",
    hiddenFromList: false,
  },
  trackDistance: {
    type: "number",
    min: 0,
    max: 1800,
    step: 10,
    default: 0,
    description: "Lead-to-value distance override; zero measures the text",
    hiddenFromList: false,
  },
  wordGap: {
    type: "number",
    min: 0,
    max: 500,
    step: 4,
    default: 220,
    description: "Gap between the lead and value",
    hiddenFromList: false,
  },
  endPadding: {
    type: "number",
    min: 0,
    max: 320,
    step: 4,
    default: 96,
    description: "Trailing edge padding for long values",
    hiddenFromList: false,
  },
  fillDuration: {
    type: "number",
    min: 8,
    max: 45,
    step: 1,
    default: 38,
    description: "Fill duration in frames",
    hiddenFromList: false,
  },
  outlineWidth: {
    type: "number",
    min: 0,
    max: 12,
    step: 0.5,
    default: 3,
    description: "Outline width",
    hiddenFromList: false,
  },
  color: {
    type: "color",
    default: "#f4f3f6",
    description: "Fill color",
  },
  outlineColor: {
    type: "color",
    default: "#e6e2ed",
    description: "Outline color",
  },
  backgroundColor: {
    type: "color",
    default: "#030012",
    description: "Background color",
  },
  glowColor: {
    type: "color",
    default: "#64109a",
    description: "Entrance glow color",
  },
  fontWeight: {
    type: "enum",
    default: "700",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["leadText","valueText","fontSize","enterOffset","anchorOffsetX","trackDistance","wordGap","endPadding","fillDuration","outlineWidth","color","outlineColor","backgroundColor","glowColor","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  leadText: "Keep",
  valueText: "100%",
  fontSize: 368,
  enterOffset: 240,
  anchorOffsetX: -84,
  trackDistance: 0,
  wordGap: 220,
  endPadding: 96,
  fillDuration: 38,
  outlineWidth: 3,
  color: "#f4f3f6",
  outlineColor: "#e6e2ed",
  backgroundColor: "#030012",
  glowColor: "#64109a",
  fontWeight: "700",
  speed: 1,
};

type OutlineFillTrackTextElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof OutlineFillTrackTextBase>;

const OutlineFillTrackTextInner = forwardRef<
  HTMLDivElement,
  OutlineFillTrackTextElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<OutlineFillTrackText>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <OutlineFillTrackTextBase
          {...(componentProps as unknown as ComponentProps<typeof OutlineFillTrackTextBase>)}
        />
      </div>
    </Sequence>
  );
});

export const OutlineFillTrackText = Interactive.withSchema({
  Component: OutlineFillTrackTextInner,
  componentName: "<OutlineFillTrackText>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
